/**
 * @event
 * @name scwin.input_47_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.input_47_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin input_47_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.openUpLawPop()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76210.input_47_onclick' }); }
};

