/**
 * @method
 * @name scwin.reg
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reg = async function () {
    /* sdd-asis-lifecycle:begin fn_reg — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const sprtRoomtitle = $c.util.getComponent('ipt_sprtRoomtitle').getValue();
    if ($.trim(sprtRoomtitle).length == 0) {
        await $c.win.alert("제목을 입력해 주세요.");
        ($c.util.getComponent('ipt_sprtRoomtitle') && $c.util.getComponent('ipt_sprtRoomtitle').setFocus ? $c.util.getComponent('ipt_sprtRoomtitle').setFocus() : ($c.util.getComponent('ipt_sprtRoomtitle') && $c.util.getComponent('ipt_sprtRoomtitle').focus ? $c.util.getComponent('ipt_sprtRoomtitle').focus() : console.warn('[sdd] focus 대상 미해결: ipt_sprtRoomtitle')));
        return;
    }
    scwin.transfer();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.transfer
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.transfer = function () {
    /* sdd-asis-lifecycle:begin fn_transfer — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    DEXT5UPLOAD.Transfer("dext5upload");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.DEXT5UPLOAD_OnTransfer_Complete
 * @author Inswave
 * @date 2026. 09. 29
 * @param dextId
 * @returns
 * @hidden N
*/
scwin.DEXT5UPLOAD_OnTransfer_Complete = async function (dextId) {
    /* sdd-asis-lifecycle:begin DEXT5UPLOAD_OnTransfer_Complete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const textNew = DEXT5UPLOAD.GetNewUploadListForText("dext5upload");
    if (textNew != null) {
        const rtn = fn_newTextToString(textNew);
        $('#ipt_attachFileInfo', $('#regForm')).val(rtn);
    }
    $('#ipt_SCREN_ID', $('#regForm')).val("/jldstf76210/jldstf76210.xml");
    $('#ipt_method', $('#regForm')).val("regSprtRoom");
    const htmlText = DEXT5.getBodyValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContn').setValue(htmlText);
    const notHtmlText = DEXT5.getBodyTextValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContnNoHtml').setValue(notHtmlText);
    if (await $c.win.confirm("저장하시겠습니까?")) {
        $('#regForm').submit();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.openUpLawPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.openUpLawPop = function () {
    /* sdd-asis-lifecycle:begin fn_openUpLawPop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = "/ods/sprtroom.do?method=readRelatedLawList&mode=popup&SCREN_ID=JLDODS76230.jsp&SCREN_PROCES_TP_CD=01";
    $c.frame.CreateDialogFrame("", (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), "상위법규목록", { width: 600, height: 700 }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setData
 * @author Inswave
 * @date 2026. 09. 29
 * @param tit no
 * @returns
 * @hidden N
*/
scwin.setData = function (tit, no) {
    /* sdd-asis-lifecycle:begin fn_setData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_upSprtRoomNoTit').setValue(tit);
    $c.util.getComponent('ipt_upSprtRoomNo').setValue(no);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.delValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.delValue = function () {
    /* sdd-asis-lifecycle:begin fn_delValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_upSprtRoomNo').setValue('00000000000000');
    $c.util.getComponent('ipt_upSprtRoomNoTit').setValue('해당없음');
    /* sdd-asis-lifecycle:end */
};
